    none = 0,
    A = 1<<0,
    B = 1<<1,
    X = 1<<3,
    Y = 1<<4,
    //% block="left shoulder"
    leftShoulder = 1<<6, 
    //% block="right shoulder"
    rightShoulder = 1<<7,
    back = 1<<10,
    start = 1<<11,
    guide = 1<<12,
    //% block="left stick"
    leftStick = 1<<13,
    //% block="right stick"
    rightStick = 1<<14
}

enum GameDirection {
    //% block="no direction"
    noDirection = 0,
    up = 1,
    //% block="up right"
    upRight = 2,
    right = 3,
    //% block="down right"
    downRight = 4,
    down = 5,
